/**
 * A single show-or-hide section with one trigger (`design/components/collapsible.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/collapsible.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import * as zag from '@zag-js/collapsible'
import { normalizeProps } from '@zag-js/solid'

import {
  Icon,
  agentMember,
  claimSlot,
  createDerived,
  elementRef,
  mergeParts,
  scope,
  useDirection,
  useMachine,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/collapsible.module.css'

export interface CollapsibleProps {
  /**
   * Strings get the content text style; components keep their own (Accordion's rule).
   */
  children: JSX.Element
  /**
   * Closed by default, because a disclosure that starts open hides nothing.
   */
  defaultOpen?: boolean
  /**
   * Keeps the closed region's content in the document and `hidden`, so a page's server markup
   * carries it and its state survives a close. Without it the React member leaves closed content
   * out. The generated members keep it in every case.
   */
  keepMounted?: boolean
  /**
   * The trigger's text, naming what is disclosed in the product's words.
   */
  label: string
  onOpenChange?: (open: boolean) => void
  /**
   * Controlled state, paired with `onOpenChange` as in Radix.
   */
  open?: boolean
}

/** A single show-or-hide section with one trigger. */
export default function Collapsible(given: CollapsibleProps): JSX.Element {
  const props = mergeProps(
    { defaultOpen: false } as Defaults<CollapsibleProps, 'defaultOpen'>,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const trigger = elementRef<HTMLElement>()
    const documentDirection = useDirection(() => trigger.value)
    const service = useMachine(
      zag.machine,
      () =>
        ({
          id: uid,
          dir: documentDirection(),
          open: props.open,
          defaultOpen: props.defaultOpen,
          onOpenChange: (details) => {
            props.onOpenChange?.(details.open)
          },
        }) as Partial<zag.Props>,
    )
    const api = createDerived(() => zag.connect(service, normalizeProps))
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'Collapsible',
        element: () => trigger.value,
        state: () => ({ open: api.value.open }),
        actions: {
          open: () => api.value.open || api.value.setOpen(true),
          close: () => api.value.open && api.value.setOpen(false),
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        {...mergeParts(api.value.getRootProps(), {
          class: styles.root,
          'data-member': 'collapsible',
        })}
      >
        {/* trigger */}
        <button
          {...mergeParts(api.value.getTriggerProps(), { class: styles.trigger })}
          ref={trigger.attach}
        >
          <span class={styles.label}>{props.label}</span>
          <span class={styles.chevron}>
            <Icon name="down" size="sm" />
          </span>
        </button>
        {/* content */}
        <div
          {...mergeParts(api.value.getContentProps(), {
            class: styles.content,
            style: {
              '--radix-collapsible-content-height': Object(api.value.getContentProps().style)[
                '--height'
              ],
            },
          })}
        >
          <div class={styles.inner}>{props.children}</div>
        </div>
      </div>
    )
  })
}
